// Command check-repo fails on source that switches a build rule off or hides from it, where no analyzer can see it.
//
// It walks the repository and reports, as path:line: [rule] message:
//
//   - pragma: a #pragma warning disable or #nullable disable without "// Justification: <why>" on the same line;
//   - suppress-message: a [SuppressMessage] or [UnconditionalSuppressMessage] without a non-empty Justification;
//   - generated: a generated-code marker (<auto-generated>, [GeneratedCode], "Code generated ... DO NOT EDIT.") or a
//     *.g.cs, *.generated.cs or *.designer.cs file outside the folders that buf writes;
//   - analyzer-config: an .editorconfig or .globalconfig other than /.editorconfig and /dotnet/.globalconfig;
//   - captured-context: ConfigureAwait(true) or ContinueOnCapturedContext (docs/guidelines/csharp.md Async);
//   - positional-record: a record with a primary constructor (docs/guidelines/csharp.md Types, VSA0002).
//
// The rules and their reasons are in docs/guidelines/csharp.md Suppressions.
// Run it from the sidecar module: go -C sidecar run ./scripts/check-repo [-root ..].
package main

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/signal"
	"path"
	"regexp"
	"slices"
	"strings"
)

// generatedDirs are written by buf (buf.gen*.yaml) and are never edited by hand.
func generatedDirs() []string {
	return []string{
		"dotnet/src/Whatsmeow.Protocol.WhatsApp/Generated/",
		"dotnet/src/Whatsmeow.Protocol/Generated/",
		"sidecar/gen/",
	}
}

// blessedConfigs are the only analyzer configuration files (docs/guidelines/csharp.md Build baseline).
func blessedConfigs() []string {
	return []string{".editorconfig", "dotnet/.globalconfig"}
}

// skippedDirs hold version control state and build output, never our source.
func skippedDirs() []string {
	return []string{".git", "dotnet/artifacts"}
}

var (
	pragmaDisable     = regexp.MustCompile(`^\s*#\s*(pragma\s+warning\s+disable|nullable\s+disable)\b`)
	justification     = regexp.MustCompile(`//\s*Justification:\s*\S`)
	suppressMessage   = regexp.MustCompile(`\[\s*(?:(?:assembly|module)\s*:\s*)?(?:System\.Diagnostics\.CodeAnalysis\.)?(?:Unconditional)?SuppressMessage(?:Attribute)?\s*\(`)
	justificationArg  = regexp.MustCompile(`Justification\s*=\s*"\s*[^"\s][^"]*"`)
	csGeneratedMarker = regexp.MustCompile(`(?i)<auto-?generated|\[\s*(?:System\.CodeDom\.Compiler\.)?GeneratedCode(?:Attribute)?\s*\(`)
	goGeneratedMarker = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)
	capturedContext   = regexp.MustCompile(`ConfigureAwait\s*\(\s*true\s*\)|ContinueOnCapturedContext`)
	positionalRecord  = regexp.MustCompile(`\brecord\s+(?:struct\s+|class\s+)?[A-Za-z_]\w*\s*(?:<[^>]*>)?\s*\(`)
	generatedFileName = regexp.MustCompile(`(?i)\.(?:g|generated|designer)\.cs$`)
)

var errFindings = errors.New("repository check failed")

func main() {
	root := flag.String("root", "..", "the repository root")
	flag.Parse()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	err := run(ctx, os.DirFS(*root), os.Stdout)
	stop()
	if err != nil {
		fmt.Fprintln(os.Stderr, "check-repo:", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, fsys fs.FS, out io.Writer) error {
	findings, err := check(ctx, fsys)
	if err != nil {
		return err
	}

	for _, f := range findings {
		_, err = fmt.Fprintln(out, f)
		if err != nil {
			return fmt.Errorf("report: %w", err)
		}
	}

	if len(findings) > 0 {
		return fmt.Errorf("%w: %d findings (docs/guidelines/csharp.md Suppressions)", errFindings, len(findings))
	}

	return nil
}

// finding is one rule violation at a line (0 when it is about the whole file).
type finding struct {
	path    string
	line    int
	rule    string
	message string
}

func (f finding) String() string {
	return fmt.Sprintf("%s:%d: [%s] %s", f.path, f.line, f.rule, f.message)
}

func check(ctx context.Context, fsys fs.FS) ([]finding, error) {
	var findings []finding

	err := fs.WalkDir(fsys, ".", func(name string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if ctx.Err() != nil {
			return fmt.Errorf("walk: %w", ctx.Err())
		}

		if entry.IsDir() {
			if isSkipped(name) {
				return fs.SkipDir
			}

			return nil
		}

		found, err := checkFile(fsys, name)
		if err != nil {
			return err
		}

		findings = append(findings, found...)

		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("walk the repository: %w", err)
	}

	return findings, nil
}

func isSkipped(name string) bool {
	base := path.Base(name)
	if base == "bin" || base == "obj" || base == "node_modules" {
		return true
	}

	return slices.Contains(skippedDirs(), name)
}

func isGenerated(name string) bool {
	return slices.ContainsFunc(generatedDirs(), func(dir string) bool { return strings.HasPrefix(name, dir) })
}

func checkFile(fsys fs.FS, name string) ([]finding, error) {
	base := path.Base(name)

	if base == ".editorconfig" || strings.HasSuffix(base, ".globalconfig") {
		if slices.Contains(blessedConfigs(), name) {
			return nil, nil
		}

		return []finding{{name, 0, "analyzer-config", "only /.editorconfig and /dotnet/.globalconfig may configure analyzers"}}, nil
	}

	switch path.Ext(name) {
	case ".cs":
		if isGenerated(name) {
			return nil, nil
		}

		content, err := fs.ReadFile(fsys, name)
		if err != nil {
			return nil, fmt.Errorf("read %s: %w", name, err)
		}

		return checkCSharp(name, content), nil
	case ".go":
		if isGenerated(name) {
			return nil, nil
		}

		content, err := fs.ReadFile(fsys, name)
		if err != nil {
			return nil, fmt.Errorf("read %s: %w", name, err)
		}

		return checkGo(name, content), nil
	default:
		return nil, nil
	}
}

func checkCSharp(name string, content []byte) []finding {
	var findings []finding

	if generatedFileName.MatchString(name) {
		findings = append(findings, finding{name, 0, "generated", "generated-code file name outside the buf output folders"})
	}

	for number, line := range lines(content) {
		if pragmaDisable.MatchString(line) && !justification.MatchString(line) {
			findings = append(findings, finding{name, number, "pragma", "add \"// Justification: <why>\" on the same line"})
		}

		if csGeneratedMarker.MatchString(line) {
			findings = append(findings, finding{name, number, "generated", "generated-code marker outside the buf output folders; analyzers would skip this file"})
		}

		if capturedContext.MatchString(line) {
			findings = append(findings, finding{name, number, "captured-context", "library code never resumes on the caller's context; use ConfigureAwait(false)"})
		}

		if positionalRecord.MatchString(line) {
			findings = append(findings, finding{name, number, "positional-record", "records use required init members, not a primary constructor (VSA0002)"})
		}
	}

	for _, at := range suppressMessage.FindAllIndex(content, -1) {
		attribute := content[at[0]:]
		if end := bytes.Index(attribute, []byte(")]")); end >= 0 {
			attribute = attribute[:end]
		}

		if !justificationArg.Match(attribute) {
			findings = append(findings, finding{name, 1 + bytes.Count(content[:at[0]], []byte("\n")), "suppress-message", "set a non-empty Justification = \"<why>\""})
		}
	}

	slices.SortStableFunc(findings, func(a, b finding) int { return a.line - b.line })

	return findings
}

func checkGo(name string, content []byte) []finding {
	var findings []finding

	for number, line := range lines(content) {
		if goGeneratedMarker.MatchString(line) {
			findings = append(findings, finding{name, number, "generated", "generated-code marker outside sidecar/gen; golangci-lint would skip this file"})
		}
	}

	return findings
}

// lines yields each line with its 1-based number, without the line ending.
func lines(content []byte) func(yield func(int, string) bool) {
	return func(yield func(int, string) bool) {
		scanner := bufio.NewScanner(bytes.NewReader(content))
		scanner.Buffer(make([]byte, 0, 64*1024), len(content)+1)

		for number := 1; scanner.Scan(); number++ {
			if !yield(number, strings.TrimSuffix(scanner.Text(), "\r")) {
				return
			}
		}
	}
}
